package tesoreria.compras.ordencompra.application.usecases;
import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import tesoreria.compras.ordencompra.OrdenCompraFixture; import tesoreria.compras.ordencompra.domain.model.*; import tesoreria.compras.ordencompra.domain.ports.out.OrdenCompraRepository; import java.time.LocalDate; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(org.mockito.junit.jupiter.MockitoExtension.class) class OrdenCompraUseCasesTest { @Mock OrdenCompraRepository repository; @InjectMocks CreateOrdenCompraUseCaseImpl create; @InjectMocks GetOrdenCompraUseCaseImpl get; @InjectMocks GetOrdenCompraByNumeroUseCaseImpl getByNumero; @InjectMocks ListOrdenCompraUseCaseImpl list; @InjectMocks UpdateOrdenCompraUseCaseImpl update; @InjectMocks TransitionOrdenCompraUseCaseImpl transition;
 @Test void executesUseCases(){var orden=OrdenCompraFixture.pendiente();when(repository.reservarSiguienteNumero(2026)).thenReturn(1L);when(repository.save(any())).thenAnswer(i->i.getArgument(0));when(repository.findById(1L)).thenReturn(Optional.of(orden));when(repository.findByIdForUpdate(1L)).thenReturn(Optional.of(orden));when(repository.findByNumero(orden.numero())).thenReturn(Optional.of(orden));when(repository.findByCriteria(any())).thenReturn(List.of(orden));assertThat(create.create(LocalDate.of(2026,8,5),8,2,"",List.of(OrdenCompraFixture.item())).numero()).isEqualTo("OC-2026-000001");assertThat(get.get(1L)).isEqualTo(orden);assertThat(getByNumero.getByNumero(orden.numero())).isEqualTo(orden);assertThat(list.list(new OrdenCompraCriteria(null,null,null,null,null))).containsExactly(orden);assertThat(update.update(1L,orden.fechaEmision(),8,2,"x",List.of(OrdenCompraFixture.item())).observaciones()).isEqualTo("x");assertThat(transition.transition(1L,OrdenCompraEstado.APROBADA).estado()).isEqualTo(OrdenCompraEstado.APROBADA);verify(repository).reservarSiguienteNumero(2026);} @Test void rejectsMissingOrder(){when(repository.findById(1L)).thenReturn(Optional.empty());when(repository.findByIdForUpdate(1L)).thenReturn(Optional.empty());assertThatThrownBy(()->get.get(1L)).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->update.update(1L,LocalDate.now(),1,1,"",List.of(OrdenCompraFixture.item()))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->transition.transition(1L,OrdenCompraEstado.APROBADA)).isInstanceOf(RuntimeException.class);} }
